function handleReturning(world, id, pos, job) {
  if (nearPoint(pos, job.homeX, job.homeY, 2)) {
    if (job.carrying) {
      const chestId = deliveryChestForJob(world, job);
      if (chestId > 0) depositCarriedItems(world, id, chestId, job);
    }
    setIdle(job, world);
    if (job.carrying) world.emit("townfolk:delivered", { actor: id, resource: job.carrying });
    job.carrying = "";
    job.carryCount = 0;
    return;
  }

  const moved = stepToward(world, id, pos, job.targetX, job.targetY);
  if (!moved) {
    job.stuckTurns++;
    if (job.stuckTurns >= MAX_STUCK_TURNS) setIdle(job, world);
    return;
  }
  job.stuckTurns = 0;
}

const BREW_STOCK_LIMIT = 10;
const BREW_POTIONS = ["potion_health", "potion_stoneskin", "potion_vigor", "potion_anti_venom"];

function countShopStock(world, shopkeeperId) {
  let count = 0;
  for (const [, unpaid] of world.query(Unpaid)) {
    if (unpaid.shopkeeperId === shopkeeperId) count++;
  }
  return count;
}

function findChestNear(world, x, y) {
  let chestId = 0;
  forEachInRadius(world, x, y, 1, (eid) => {
    if (chestId) return;
    if (!world.has(eid, Inventory)) return;
    const ni = world.get(eid, NamedIdentity);
    const identity = String(ni?.identity || "");
    const name = String(ni?.name || "");
    if (identity.endsWith("_chest") || identity === "chest" || name.endsWith(" Chest")) chestId = eid;
  });
  return chestId;
}

function deliveryChestForJob(world, job) {
  const storage = _cachedStorage || (world ? findTownContainers(world) : null);
  if (!storage) return 0;
  switch (job.workSiteKind) {
    case "haul_flour":
    case "haul_firewood":
    case "fetch_water":
    case "fish":
      return storage.tavern || 0;
    case "haul_lumber":
      return storage.smithy || 0;
    default:
      break;
  }

  switch (job.carrying) {
    case "crops":
    case "flour":
      return storage.mill || 0;
    case "ore":
      return storage.smithy || 0;
    case "wood":
    case "lumber":
    case "firewood":
      return storage.lumber || 0;
    case "herbs":
      return storage.herb || 0;
    case "water":
    case "fish":
      return storage.tavern || 0;
    default:
      return 0;
  }
}

function handleDelivering(world, id, pos, job) {
  if (!job.carrying) {
    setIdle(job, world);
    return;
  }
  const deliveryX = job.deliverX || job.targetX;
  const deliveryY = job.deliverY || job.targetY;
  if (nearPoint(pos, deliveryX, deliveryY, 1)) {
    const chestId = findChestNear(world, deliveryX, deliveryY) || deliveryChestForJob(world, job);
    const moved = chestId ? depositCarriedItems(world, id, chestId, job) : 0;
    if (!moved && carriedItemCount(world, id, job) <= 0) {
      job.carrying = "";
      job.carryCount = 0;
    }
    world.emit("townfolk:delivered", { actor: id, resource: job.carrying });
    if (carriedItemCount(world, id, job) <= 0) {
      job.carrying = "";
      job.carryCount = 0;
    }
    job.state = TOWNFOLK_STATES.returning;
    job.targetX = job.homeX;
    job.targetY = job.homeY;
    job.stuckTurns = 0;
    return;
  }
  const moved = stepToward(world, id, pos, job.targetX, job.targetY);
  if (!moved) {
    job.stuckTurns++;
    if (job.stuckTurns >= MAX_STUCK_TURNS) {
      job.state = TOWNFOLK_STATES.returning;
      job.targetX = job.homeX;
      job.targetY = job.homeY;
      job.stuckTurns = 0;
    }
    return;
  }
  job.stuckTurns = 0;
}

