  return { phase, ...getRoleWorkTarget(world, job) };
}

function emitRoleWork(world, id, pos, job, target) {
  switch (target.kind) {
    case "tend":
      world.emit("townfolk:tended", { actor: id, x: pos.x, y: pos.y });
      break;
    case "mill":
      world.emit("audio:play", { key: "action:millstone_grind", at: { x: pos.x | 0, y: pos.y | 0 }, sourceId: id });
      world.emit("townfolk:milled", { actor: id, x: pos.x, y: pos.y });
      break;
    case "forge_tools":
      world.emit("townfolk:forged", { actor: id, x: pos.x, y: pos.y });
      break;
    case "minister":
    case "pray":
      world.emit("townfolk:blessed", { actor: id, x: pos.x, y: pos.y });
      break;
    case "cook":
      world.emit("townfolk:cooked", { actor: id, x: pos.x, y: pos.y });
      break;
    case "serve":
    case "pour":
      world.emit("townfolk:poured", { actor: id, x: pos.x, y: pos.y });
      break;
    case "haul":
    case "garden":
      world.emit("townfolk:worked", { actor: id, x: pos.x, y: pos.y, kind: target.kind });
      break;
    case "inspect":
      world.emit("townfolk:inspected", { actor: id, x: pos.x, y: pos.y });
      break;
    case "sort_herbs":
      world.emit("townfolk:sorted_herbs", { actor: id, x: pos.x, y: pos.y });
      break;
    case "stock_shelves":
      world.emit("townfolk:stocked", { actor: id, x: pos.x, y: pos.y });
      break;
    case "pub":
      world.emit("townfolk:unwound", { actor: id, x: pos.x, y: pos.y });
      break;
    case "sleep":
      world.emit("townfolk:slept", { actor: id, x: pos.x, y: pos.y });
      break;
    default:
      break;
  }

  if (
    target.kind === "chop"
    || target.kind === "mine"
    || target.kind === "repair"
    || target.kind === "harvest_crop"
    || target.kind === "plant_crop"
    || target.kind === "harvest_herb"
    || target.kind === "brew"
    || target.kind === "mill"
    || target.kind === "forge_tools"
    || target.kind === "cook"
    || target.kind === "fetch_water"
    || target.kind === "fish"
    || target.kind === "haul_flour"
    || target.kind === "haul_firewood"
    || target.kind === "haul_lumber"
  ) {
    if (shouldPauseForLabor(world, id, job, target.kind)) {
      job.workTurns = 1;
      return;
    }
    job.workSiteKind = target.kind;
    job.workTurns = 0;
    handleWorking(world, id, pos, job);
    return;
  }

  job.workTurns = 2 + Math.floor(world.rand() * 3);
}

function handleScheduledTownfolk(world, id, pos, job) {
  const target = getScheduleTarget(world, id, job);
  const phaseChanged = target.phase !== job.lastPhase;
  if (Number.isFinite(target.deliverX)) job.deliverX = target.deliverX;
  if (Number.isFinite(target.deliverY)) job.deliverY = target.deliverY;

  if (target.kind !== "sleep" && isAsleep(world, id)) {
    tryWakeActor(world, id, { reason: "scheduled_wake", intensity: 999 });
  }

  // Let active delivery complete before schedule override
  if (!phaseChanged && job.state === TOWNFOLK_STATES.delivering && job.carrying) {
    handleDelivering(world, id, pos, job);
    return;
  }

  if (phaseChanged) {
    job.lastPhase = target.phase;
    job.workTurns = 0;
    job.stuckTurns = 0;
    job.routineKind = target.kind;
    if (job.carrying && carriedItemCount(world, id, job) > 0) {
      handleDelivering(world, id, pos, job);
      return;
    }
    if (job.carrying) {
      world.emit("townfolk:delivered", { actor: id, resource: job.carrying });
      job.carrying = "";
      job.carryCount = 0;
    }
    world.emit("townfolk:routine", { actor: id, phase: target.phase, kind: target.kind });

    // Shop vendors open their door when the work phase starts.
    if (target.phase === "work" && findOwnedShopRoomByActor(world, id)) {
      openOwnedShopDoors(world, id);
    }
  }

  job.targetX = target.x;
  job.targetY = target.y;
  job.workSiteKind = target.kind;
  job.routineKind = target.kind;

  const targetRadius = effectiveScheduleRadius(world, target.x, target.y, target.radius);
  if (!nearPoint(pos, target.x, target.y, targetRadius)) {
    job.state = TOWNFOLK_STATES.walking;
    const moved = stepToward(world, id, pos, target.x, target.y);
    if (!moved) {
      job.stuckTurns++;
      if (job.stuckTurns >= MAX_STUCK_TURNS) {
        job.stuckTurns = 0;
        job.state = target.state;
      }
      return;
    }
    job.stuckTurns = 0;
    return;
  }

  job.state = target.state;
  job.stuckTurns = 0;
  if (target.kind === "sleep") {
    putActorToSleep(world, id, {
      reason: "scheduled_rest",
      wakeDifficulty: 6,
      wakeRadius: 1,
      wakeOnDamage: true,
    });
    return;
  }
  if (target.kind === "home") return;
  if (job.workTurns > 0) {
    job.workTurns--;
    return;
  }
  emitRoleWork(world, id, pos, job, target);
}

